do $do$
declare p jsonb := $pl$[{"k":"APBIO-MCQ-114","t":"Lipids","s":"A student compares three fat samples whose fatty acid chains have the same length but different numbers of carbon–carbon double bonds. The student records the following results.\n\nSample | Double bonds per fatty acid chain | Melting temperature (°C)\nX | 0 | 60\nY | 1 | 15\nZ | 2 | −5\n\nWhich statement best describes the relationship in the data and explains it using fatty acid structure?","a":"B","c":[["A","More double bonds are associated with higher melting temperatures because unsaturated fatty acid chains are straighter and pack more closely.",false,"Reversed-trend trap: The recorded melting temperatures decrease, rather than increase, with more double bonds. Unsaturated chains have kinks, rather than being straighter. Fix: Track melting temperature from zero to two double bonds before describing the trend."],["B","More double bonds are associated with lower melting temperatures because kinks in unsaturated fatty acid chains interfere with close packing.",true,"Melting temperature decreases from 60°C to −5°C as the number of double bonds increases. Double bonds introduce kinks that prevent close packing, helping explain why more unsaturated fats remain liquid at lower temperatures."],["C","More double bonds are associated with lower melting temperatures because double bonds make the fats hydrophilic.",false,"Polarity-confusion trap: The trend is described accurately, but unsaturation does not make these fats hydrophilic. Fats remain generally nonpolar; chain kinks explain the melting-temperature pattern. Fix: Distinguish changes in chain shape from changes in attraction to water."],["D","More double bonds are associated with lower melting temperatures because adding double bonds makes the fatty acid chains more saturated.",false,"Saturation-definition trap: The trend is described accurately, but adding double bonds increases unsaturation, not saturation. Saturated fatty acid chains contain only single carbon–carbon bonds. Fix: Check for carbon–carbon double bonds before classifying a fatty acid as saturated."]]},{"k":"APBIO-MCQ-SV-114-v1","t":"Lipids","s":"A bakery tests three fat blends to find one that stays mostly liquid at 20°C. The fatty acid chains are equal in length across the blends. Measurements at 20°C give these results:\n\nBlend | Average carbon–carbon double bonds per fatty acid chain | Percentage of fat that is liquid\nP | 0 | 0%\nQ | 1 | 60%\nR | 2 | 100%\n\nWhich statement accurately describes the pattern and connects it to fatty acid structure?","a":"A","c":[["A","As double bonds become more numerous, the liquid percentage increases because kinked fatty acid chains cannot pack as closely.",true,"The liquid percentage rises from 0% to 100% as the average double-bond count increases. Double bonds introduce chain kinks that disrupt close packing, helping more unsaturated fats remain liquid at the test temperature."],["B","As double bonds become more numerous, the liquid percentage decreases because unsaturated fatty acid chains are straight and pack tightly.",false,"Reversed-trend trap: The liquid percentage increases, not decreases, with double-bond count. Unsaturated chains contain kinks rather than being straight. Fix: Follow the liquid percentages as double-bond count rises before stating the relationship."],["C","As double bonds become more numerous, the liquid percentage increases because the fats become hydrophilic.",false,"Polarity-confusion trap: This identifies the observed increase but incorrectly attributes it to attraction to water. Unsaturation changes chain shape without making these generally nonpolar fats hydrophilic. Fix: Separate changes in chain shape from changes in water attraction."],["D","As double bonds become more numerous, the liquid percentage increases because the fatty acid chains become more saturated.",false,"Saturation-definition trap: The liquid-percentage pattern is accurate, but more double bonds mean greater unsaturation. Saturated fatty acid chains have only single carbon–carbon bonds. Fix: Count carbon–carbon double bonds before deciding whether saturation increases."]]},{"k":"APBIO-MCQ-SV-114-v2","t":"Lipids","s":"A skin-care company is selecting a fat blend for a lotion stored at cool temperatures. All fatty acid chains in the blends have the same length, and each unsaturated chain contains one carbon–carbon double bond. The company obtains these measurements:\n\nBlend | Saturated fatty acid chains (%) | Melting temperature (°C)\nRose | 20 | 5\nFern | 50 | 18\nMoss | 80 | 32\n\nWhich statement correctly summarizes the measured relationship and connects it to fatty acid structure?","a":"D","c":[["A","Blends with a greater percentage of saturated chains melt at lower temperatures because saturated chains have more kinks.",false,"Reversed-trend trap: The measurements show increasing, not decreasing, melting temperatures as the saturated proportion rises. The structural explanation also reverses the relationship: double bonds in unsaturated chains introduce kinks. Fix: Follow the temperature values as the saturated percentage increases, then check which chains contain kinks."],["B","Blends with a greater percentage of saturated chains melt at higher temperatures because saturation makes fats hydrophilic.",false,"Polarity-confusion trap: The temperature pattern is described correctly, but saturation does not make fats hydrophilic. Differences in chain shape and packing, rather than attraction to water, explain this pattern. Fix: Separate a change in chain packing from a change in water attraction."],["C","Blends with a greater percentage of saturated chains melt at higher temperatures because saturated chains contain more carbon–carbon double bonds.",false,"Saturation-definition trap: The measured trend is accurate, but the definition of saturation is reversed. Saturated fatty acid chains have only single carbon–carbon bonds; double bonds indicate unsaturation. Fix: Identify the carbon–carbon bond types before deciding whether a chain is saturated."],["D","Blends with a greater percentage of saturated chains melt at higher temperatures because straighter chains can pack more closely.",true,"Melting temperature rises from 5°C to 32°C as the saturated proportion increases from 20% to 80%. Saturated chains lack the double-bond kinks of unsaturated chains, allowing closer packing that helps explain the higher melting temperatures."]]},{"k":"APBIO-MCQ-SV-114-v3","t":"Lipids","s":"An animal-feed supplier needs a fat that remains solid in a cool warehouse. Three candidate fats have equal-length fatty acid chains but differ in their degree of unsaturation. Testing produces the following measurements:\n\nFat | Average carbon–carbon double bonds per fatty acid chain | Melting temperature (°C)\nCedar | 3 | −12\nMaple | 2 | 8\nPine | 0 | 48\n\nAs the average number of double bonds decreases, which statement describes the measured trend and explains its structural basis?","a":"D","c":[["A","Melting temperature falls because fatty acid chains with fewer double bonds have more kinks and pack less closely.",false,"Reversed-trend trap: The measurements show rising melting temperatures as double bonds decrease, not falling temperatures. Removing double bonds also reduces the kinks associated with unsaturation rather than adding them. Fix: Follow the rows from three double bonds to zero and compare their melting temperatures."],["B","Melting temperature rises because fatty acid chains with fewer double bonds make the fats hydrophilic.",false,"Polarity-confusion trap: This identifies the temperature trend but incorrectly attributes it to attraction to water. These fats remain generally hydrophobic; differences in chain shape and packing explain the pattern. Fix: Separate the number of chain kinks from whether a fat interacts favorably with water."],["C","Melting temperature rises because fatty acid chains with fewer double bonds are more unsaturated.",false,"Saturation-definition trap: This matches the measured temperature trend but reverses the meaning of unsaturation. Fewer carbon–carbon double bonds indicate less unsaturation, and chains with none are saturated. Fix: Count carbon–carbon double bonds before comparing the degree of unsaturation."],["D","Melting temperature rises because fatty acid chains with fewer kinks can pack together more closely.",true,"Moving from three double bonds to zero, the measured melting temperature rises from −12°C to 48°C. Fewer double bonds mean fewer chain kinks, allowing closer packing and helping explain the higher melting temperature."]]},{"k":"APBIO-MCQ-115","t":"Lipids","s":"A change in a mammal’s diet increases the proportion of unsaturated fatty acids in its stored fats. The total mass of stored fat and the lengths of the fatty acid chains remain unchanged. At the same temperature, which prediction best connects the structural change to the properties and function of the stored fats?","a":"D","c":[["A","The stored fats will tend to be less liquid while continuing to serve as a long-term energy reserve.",false,"Reversed packing effect: This prediction treats double bonds as promoting tighter packing. Their kinks instead reduce close packing, so increased unsaturation favors a more liquid state at the same temperature. Fix: Trace double bonds → kinks → reduced packing before predicting physical state."],["B","The stored fats will tend to be more liquid and become water-soluble, preventing them from serving as an energy reserve.",false,"Liquid–soluble confusion: A more liquid state does not mean greater water solubility. Increasing unsaturation does not make fats hydrophilic or remove their energy-storage function. Fix: Evaluate physical state and water solubility separately."],["C","The stored fats will tend to be more liquid and form phospholipid bilayers instead of serving as an energy reserve.",false,"Lipid-class interchangeability: This prediction assigns the membrane-forming role of phospholipids to fats. Altering fatty acid unsaturation does not convert stored fats into phospholipids. Fix: Identify the lipid class before assigning its biological function."],["D","The stored fats will tend to be more liquid while continuing to serve as a long-term energy reserve.",true,"Unsaturated fatty acids contain carbon–carbon double bonds that introduce kinks, reducing close packing and favoring a more liquid state. Changing the degree of unsaturation does not eliminate the energy-storage function of fats."]]},{"k":"APBIO-MCQ-SV-115-v1","t":"Lipids","s":"Researchers develop a soybean variety that produces seed storage fats with a greater proportion of saturated fatty acids than the original variety. Both varieties store the same mass of fat, and their fatty acid chains have the same lengths. When the seeds are compared at the same temperature, which prediction best connects the altered fatty acid composition to the properties and function of the fats?","a":"A","c":[["A","The new variety’s storage fats will tend to be less liquid but will retain their role as an energy reserve.",true,"A higher proportion of saturated fatty acids means fewer double-bond kinks, allowing closer packing and favoring a less liquid state. This structural change does not change the fats’ biological role in storing energy."],["B","The new variety’s storage fats will tend to be more liquid but will retain their role as an energy reserve.",false,"Reversed packing effect: This prediction incorrectly associates increased saturation with looser packing. Saturated fatty acid chains lack double-bond kinks, allowing closer packing and favoring a less liquid state. Fix: Compare chain kinks and packing before predicting which fat will be more liquid."],["C","The new variety’s storage fats will tend to be less liquid and become water-soluble, losing their role as an energy reserve.",false,"Liquid–soluble confusion: This prediction treats a change in physical state as a change in water solubility. Increasing saturation does not make storage fats hydrophilic or eliminate their energy-storage function. Fix: Assess physical state and water solubility as separate properties."],["D","The new variety’s storage fats will tend to be less liquid and assemble into phospholipid bilayers, replacing their role as an energy reserve.",false,"Lipid-class interchangeability: This prediction gives storage fats the bilayer-forming function of phospholipids. Increasing fatty acid saturation does not transform fats into a different lipid class. Fix: Identify whether the material is fat or phospholipid before predicting its function."]]},{"k":"APBIO-MCQ-SV-115-v2","t":"Lipids","s":"A mutation in a freshwater alga causes the fatty acids in its stored oil droplets to carry more carbon–carbon double bonds per chain than in nonmutant cells. The mutant and nonmutant cells store equal masses of oil, and chain lengths are identical. If both are kept at the same temperature, what is the most likely effect of the mutation on the stored oil?","a":"D","c":[["A","The oil will tend to be more solid, and it will still function as a stored energy reserve.",false,"Reversed packing effect: this assumes double bonds help tails pack closer together. Kinks from double bonds actually spread the tails apart, lowering packing and making the oil more fluid. Fix: Trace double bonds to kinks to packing before predicting fluidity."],["B","The oil will tend to be more fluid and will dissolve into the watery cytoplasm, so it can no longer be stored.",false,"Liquid–soluble confusion: this treats becoming more fluid as becoming water-soluble. Unsaturated fatty acid tails are still nonpolar hydrocarbons, so the oil stays hydrophobic and remains in droplets. Fix: Judge physical state and polarity as two separate questions."],["C","The oil will tend to be more fluid and will assemble into membrane bilayers instead of being stored.",false,"Lipid-class interchangeability: this gives stored fats the bilayer-forming role of phospholipids. Adding double bonds changes tail shape but does not convert a fat into an amphipathic phospholipid. Fix: Identify which lipid class is present before assigning a function."],["D","The oil will tend to be more fluid, and it will still function as a stored energy reserve.",true,"Additional double bonds create more kinks in the fatty acid tails, so the molecules cannot pack as tightly and the oil stays more fluid at a given temperature. The molecules remain hydrophobic fats, so their role in energy storage is unchanged."]]},{"k":"APBIO-MCQ-SV-115-v3","t":"Lipids","s":"A soil fungus exposed to a new growth condition replaces some saturated fatty acids in its stored fats with unsaturated fatty acids. Measurements show no change in total stored-fat mass or fatty acid chain length. Compared with reserves produced under the original condition, what change in the properties and function of these fats is most likely at an identical temperature?","a":"A","c":[["A","The reserves become more liquid but remain hydrophobic fats that store energy.",true,"Additional carbon–carbon double bonds introduce kinks that limit tight packing, making the fats more liquid at the comparison temperature. This structural change neither makes the fats water-soluble nor changes their role as energy reserves."],["B","The reserves become less liquid but remain hydrophobic fats that store energy.",false,"Reversed packing effect: This prediction assumes that greater unsaturation allows fatty acid chains to pack more closely. Double-bond kinks interfere with close packing, favoring increased rather than decreased liquidity. Fix: Sketch straight and kinked chains, then compare how closely they can pack."],["C","The reserves become more liquid and dissolve in water, losing their energy-storage role.",false,"Liquid–soluble confusion: This prediction treats becoming liquid as becoming water-soluble. Unsaturated fats remain hydrophobic and can still function as energy reserves. Fix: Check whether the change affects packing, water solubility, or both."],["D","The reserves become more liquid and assemble into phospholipid bilayers, replacing their energy-storage role.",false,"Lipid-class interchangeability: This prediction incorrectly turns a change within stored fats into a change of lipid class. Increasing unsaturation does not create phospholipids or transfer their bilayer-forming function to fats. Fix: Name the lipid class before predicting whether its biological role changes."]]},{"k":"APBIO-MCQ-116","t":"Nucleic Acids","s":"Two DNA segments have the same length and the same total number of each base, but their bases occur in different orders. Which statement best explains how the biological information stored in these segments compares?","a":"B","c":[["A","They must store the same information because they contain the same number of nucleotides.",false,"Length-only trap: This confuses the amount of DNA with its information content. Equal-length segments can have different nucleotide sequences. Fix: Compare base order rather than counting only the nucleotides."],["B","They can store different information because information is encoded in the order of their nucleotides.",true,"DNA stores biological information in its nucleotide sequence. Different base orders can encode different information even when segment length and total base counts are identical."],["C","They must store the same information because they contain the same total number of each base.",false,"Base-count trap: This treats base composition as equivalent to base sequence. Counting each base does not reveal the order in which the bases occur. Fix: Write out the sequences and compare the bases position by position."],["D","They must store the same information because both have repeating sugar-phosphate backbones.",false,"Backbone-as-information trap: This assigns information storage to the repeating backbone rather than the variable base sequence. DNA segments share the same backbone components but can encode different information. Fix: Identify which nucleotide component varies along each DNA strand."]]},{"k":"APBIO-MCQ-SV-116-v1","t":"Nucleic Acids","s":"A researcher synthesizes two RNA molecules, each 30 nucleotides long. Each contains exactly 9 adenines, 6 uracils, 8 guanines, and 7 cytosines, but the bases are arranged in a different order in each molecule. What best explains whether these two RNA molecules could carry different genetic messages?","a":"D","c":[["A","They must carry the same message, because each molecule is built from 30 nucleotides.",false,"Length-only trap: this equates how many nucleotides a molecule has with what it encodes. Two strands of equal length can hold entirely different sequences. Fix: Compare the order of bases, not just the number of nucleotides."],["B","They must carry the same message, because both contain identical numbers of A, U, G, and C.",false,"Base-count trap: this treats base composition as if it were base sequence. Tallying each base says nothing about where each base sits along the strand. Fix: Line up both sequences and compare them base by base."],["C","They must carry the same message, because both share the same repeating ribose-phosphate backbone.",false,"Backbone-as-information trap: this places the message in the backbone, which repeats identically along every RNA strand. Only the bases vary, so the backbone cannot distinguish one message from another. Fix: Ask which nucleotide component changes from position to position along the strand."],["D","They could carry different messages, because the information in a nucleic acid is determined by the sequence of its bases.",true,"Nucleic acids encode information in the order of their nucleotides. Two molecules with identical length and identical base counts can still differ in sequence, so they can specify different messages."]]}]$pl$::jsonb; r jsonb; c jsonb; v_ci uuid; v_civ uuid; n int;
begin
  if jsonb_array_length(p) <> 10 then raise exception 'chunk size'; end if;
  if exists (select 1 from app.content_items ci where ci.exam_pack_version_id='2d88ba5e-a6a3-43b8-bfae-9e5505a178a7' and ci.content_key in (select x->>'k' from jsonb_array_elements(p) x))
    then raise exception 'chunk already loaded'; end if;
  for r in select * from jsonb_array_elements(p) loop
    insert into app.content_items (exam_pack_version_id, content_key, item_type, title, status)
    values ('2d88ba5e-a6a3-43b8-bfae-9e5505a178a7', r->>'k', 'mcq', r->>'t', 'draft') returning id into v_ci;
    insert into app.content_item_versions (content_item_id, version_num, stem, stimulus, content_hash, status, review_status, canonical_answer_1)
    values (v_ci, 1, r->>'s', null, md5(r->>'k'), 'draft', 'tutor_review_pending', r->>'a') returning id into v_civ;
    for c in select * from jsonb_array_elements(r->'c') loop
      insert into app.mcq_choices (content_item_version_id, choice_key, choice_text, is_correct, rationale)
      values (v_civ, c->>0, c->>1, (c->>2)::boolean, c->>3);
    end loop;
  end loop;
  select count(*) into n from app.content_items ci join app.content_item_versions v on v.content_item_id=ci.id join app.mcq_choices m on m.content_item_version_id=v.id
   where ci.exam_pack_version_id='2d88ba5e-a6a3-43b8-bfae-9e5505a178a7' and ci.status='draft' and ci.content_key in (select x->>'k' from jsonb_array_elements(p) x);
  if n <> 40 then raise exception 'chunk 6: expected 40 choice rows, got %', n; end if;
  raise notice 'chunk 6: loaded 10 draft items';
end
$do$;
